//! LLM cluster executor via vibe-cluster.
//! See [`crate::engine`] module-level docs for context on run types.

use std::time::Duration;

use anyhow::Result;
use vibe_cluster::BatchOptions;
use vibe_cluster::Prompt;

use crate::configs::app::AppConfig;
use crate::models::action::ActionRun;
use crate::output::output::OutputKind;
use crate::print_template;
use crate::utils;
use crate::utils::escape;

/// Distributed cluster execution response payload.
pub struct ClusterResult {
    /// Normalized text response generated by the cluster node model.
    pub result: String,
}

pub struct Cluster;

impl Cluster {
    /// Execute an LLM prompt batch concurrently across the distributed cluster.
    pub async fn exec(
        system: &str,
        retries: u32,
        run: &ActionRun,
        prompt: &str,
        images: Option<Vec<String>>,
    ) -> Result<ClusterResult> {
        let config = AppConfig::instance()?;
        let cluster = config.create_cluster_filtered(run)?;

        let options = BatchOptions {
            retries: Some(retries as usize),
            ..BatchOptions::default()
        };

        let cluster_prompts: Vec<Prompt> = vec![Prompt {
            key: None,
            user: escape::unescape_text(prompt),
            system: Some(system.to_string()),
            images: images.clone(),
            history: Vec::new(),
        }];

        let cluster_results = cluster
            .batch_call_with_options(
                &cluster_prompts,
                &options,
                move |result, _current, _total| {
                    let image_info = result
                        .prompt
                        .images
                        .as_ref()
                        .map(|imgs| {
                            let size: usize = imgs.iter().map(|i| i.len()).sum();
                            format!(", {} image", utils::format::format_bytes(size))
                        })
                        .unwrap_or_default();

                    let role_label = AppConfig::instance()
                        .ok()
                        .and_then(|c| c.cluster.iter().find(|n| n.model == result.model))
                        .and_then(|n| n.role.as_ref())
                        .map(|r| r.to_string())
                        .unwrap_or_else(|| "llm".to_string());

                    // Provider-reported facts only: no stats → no duration,
                    // no input report → no tokens in the line.
                    let (duration, tokens) = match result.stats.as_ref() {
                        Some(stats) => (
                            format!(
                                " | {}",
                                utils::format::format_duration(Duration::from_millis(
                                    stats.duration_ms
                                ))
                            ),
                            stats
                                .input_tokens
                                .map(|n| format!(" ({n} tokens)"))
                                .unwrap_or_default(),
                        ),
                        None => (String::new(), String::new()),
                    };

                    print_template!(
                        OutputKind::Progress,
                        "[{role}] node: {model}{duration}{tokens}{image}",
                        "role" => role_label,
                        "model" => result.model,
                        "duration" => duration,
                        "tokens" => tokens,
                        "image" => image_info,
                    );
                },
            )
            .await
            .map_err(|e| anyhow::anyhow!("Cluster call failed: {}", e))?;

        let result = cluster_results
            .into_iter()
            .next()
            .ok_or_else(|| anyhow::anyhow!("Cluster returned no results"))?;

        if let Some(err) = result.error {
            anyhow::bail!("Cluster node execution failed: {}", err);
        }

        let text = result
            .text
            .ok_or_else(|| anyhow::anyhow!("Cluster returned empty result"))?;

        Ok(ClusterResult {
            result: vibe_cluster::normalize_text(&text),
        })
    }
}
